import os

from .errors import WSpawnError
from ._winapi import (
    is_windows,
    get_handle_information,
    set_handle_information,
    HANDLE_FLAG_INHERIT,
)


def _as_number(handle):
    try:
        return int(handle)
    except (TypeError, ValueError):
        raise WSpawnError("handle must be an integer, got %r" % (handle,), kind="badarg")


def set_inheritable(handle, enabled=True):
    """Mark ``handle`` as transferable to child processes, or stop it being so.

    On Windows, this uses SetHandleInformation to modify the HANDLE_FLAG_INHERIT flag.
    For handles that don't support inheritance (e.g., certain pseudo-handles),
    raises WSpawnError with kind="unsupported".
    """
    number = _as_number(handle)

    if not is_windows():
        # Fallback for non-Windows (though task says we only target Windows)
        try:
            os.set_inheritable(number, bool(enabled))
        except OSError as exc:
            raise WSpawnError(str(exc), kind="os", handle=handle) from exc
        except (TypeError, ValueError) as exc:
            raise WSpawnError(str(exc), kind="badarg", handle=handle) from exc
        return

    try:
        set_handle_information(number, inherit=bool(enabled))
    except OSError as exc:
        # Check if this is because the handle doesn't support inheritance
        # ERROR_INVALID_HANDLE (6) or similar might indicate unsupported
        err_code = exc.errno if hasattr(exc, 'errno') else None
        # Some handles (like console input/output in certain modes) may not support
        # SetHandleInformation. We treat specific errors as "unsupported".
        # EINVAL (22) or ERROR_INVALID_PARAMETER (87) often means unsupported operation
        if err_code in (22, 87, 6):  # EINVAL, ERROR_INVALID_PARAMETER, ERROR_INVALID_HANDLE
            raise WSpawnError(
                "handle does not support inheritance control: %s" % exc,
                kind="unsupported",
                handle=handle
            ) from exc
        raise WSpawnError(str(exc), kind="os", handle=handle) from exc


def is_inheritable(handle):
    """Return ``True`` when ``handle`` is currently transferable.

    On Windows, this uses GetHandleInformation to check the HANDLE_FLAG_INHERIT flag.
    """
    number = _as_number(handle)

    if not is_windows():
        try:
            return bool(os.get_inheritable(number))
        except OSError as exc:
            raise WSpawnError(str(exc), kind="os", handle=handle) from exc

    try:
        flags = get_handle_information(number)
        return (flags & HANDLE_FLAG_INHERIT) != 0
    except OSError as exc:
        err_code = exc.errno if hasattr(exc, 'errno') else None
        if err_code in (6,):  # ERROR_INVALID_HANDLE
            raise WSpawnError(
                "invalid handle: %s" % exc,
                kind="os",
                handle=handle
            ) from exc
        raise WSpawnError(str(exc), kind="os", handle=handle) from exc


def inheritable_handles():
    """Return every object in this process that is currently transferable.

    Note: Enumerating all handles in a process requires NtQuerySystemInformation
    which is complex. This function returns an empty tuple as a safe default.
    The caller should track handles they open themselves.
    """
    return ()

