from ._winapi import (
    is_windows,
    file_type,
    FILE_TYPE_DISK,
    FILE_TYPE_CHAR,
    FILE_TYPE_PIPE,
    FILE_TYPE_UNKNOWN,
)


def handle_kind(handle):
    """Return ``"file"``, ``"pipe"``, ``"console"`` or ``"unknown"``.

    On Windows, uses GetFileType to determine the type of the handle.
    For invalid handles, raises WSpawnError with kind="os".
    """
    try:
        number = int(handle)
    except (TypeError, ValueError):
        raise WSpawnError("handle must be an integer, got %r" % (handle,), kind="badarg")

    if not is_windows():
        # Non-Windows fallback
        if number < 0:
            raise WSpawnError("not a usable object handle: %r" % (handle,), kind="os", handle=handle)
        return "unknown"

    try:
        ft = file_type(number)
    except OSError as exc:
        # GetFileType failed - this likely means invalid handle
        raise WSpawnError(
            "cannot determine handle type: %s" % exc,
            kind="os",
            handle=handle
        ) from exc

    if ft == FILE_TYPE_DISK:
        return "file"
    elif ft == FILE_TYPE_PIPE:
        return "pipe"
    elif ft == FILE_TYPE_CHAR:
        # FILE_TYPE_CHAR can be console or other character device
        # We'll call it "console" for character devices
        return "console"
    else:
        # FILE_TYPE_UNKNOWN or FILE_TYPE_REMOTE
        return "unknown"

