        if isinstance(stdout, int):
            stdout_handle = stdout
        elif hasattr(stdout, 'fileno'):
            stdout_handle = stdout.fileno()
        elif stdout is subprocess.DEVNULL:
            # We'll handle DEVNULL specially
            stdout_handle = -1  # Special marker
        else:
            raise WSpawnError("stdout must be an integer handle or file object", kind="badarg")

