            raise WSpawnError(str(exc), kind="os") from exc
    else:
        # Non-Windows fallback using subprocess
        kwargs = {
            "close_fds": True,  # On POSIX, close_fds is safe and desired
            "stdin": stdin,
            "stdout": stdout,
            "stderr": stderr,
        }

        # For non-Windows, we can't do precise handle inheritance the same way
        # But since the task says we only target Windows, this is just a fallback
        try:
            popen = subprocess.Popen(command, **kwargs)
        except OSError as exc:
            raise WSpawnError(str(exc), kind="os") from exc
        return SpawnedProcess(popen, handles)

