        return SpawnedProcess(popen, handles)

"""Starting helper processes with a handover of the caller's objects."""

import os
import sys
import subprocess

from .errors import WSpawnError
from ._winapi import (
    is_windows,
    create_process_with_handle_list,
    wait_for_single_object,
    get_exit_code_process,
    terminate_process,
    close_handle,
)


class SpawnedProcess(object):
    """A helper process started by :func:`spawn`."""

    def __init__(self, popen_or_handles, inherit, proc_handle=None, thread_handle=None):
        # Support both subprocess.Popen (legacy/fallback) and direct handle mode
        if isinstance(popen_or_handles, subprocess.Popen):
            self._popen = popen_or_handles
            self._proc_handle = None
            self._thread_handle = None
            self._direct_mode = False
        else:
            # Direct mode: we have raw handles from CreateProcess
            self._popen = None
            self._proc_handle = proc_handle
            self._thread_handle = thread_handle
            self._direct_mode = True

        self.inherit = tuple(inherit)

        if self._direct_mode:
            self.pid = popen_or_handles  # This is actually the pid in direct mode
            self.returncode = None
        else:
            self.pid = popen_or_handles.pid
            self.returncode = None

    def wait(self, timeout=None):
        if self._direct_mode:
            if self.returncode is not None:
                return self.returncode

            if self._proc_handle is None:
                raise WSpawnError("process handle already closed", kind="os")

            # Convert timeout to milliseconds
            if timeout is None:
                timeout_ms = 0xFFFFFFFF  # INFINITE
            else:
                timeout_ms = int(timeout * 1000)

            result = wait_for_single_object(self._proc_handle, timeout_ms)
            # WAIT_OBJECT_0 = 0, WAIT_TIMEOUT = 258
            if result == 0:
                # Process finished
                self.returncode = get_exit_code_process(self._proc_handle)
                return self.returncode
            elif result == 258:
                # Timeout
                raise subprocess.TimeoutExpired(None, timeout)
            else:
                raise WSpawnError("wait failed with code %d" % result, kind="os")
        else:
            self.returncode = self._popen.wait(timeout=timeout)
            return self.returncode

    def poll(self):
        if self._direct_mode:
            if self.returncode is not None:
                return self.returncode

            if self._proc_handle is None:
                return None

            try:
                code = get_exit_code_process(self._proc_handle)
                # STILL_ACTIVE = 259
                if code == 259:
                    return None
                self.returncode = code
                return self.returncode
            except OSError:
                return None
        else:
            self.returncode = self._popen.poll()
            return self.returncode

    def terminate(self):
        if self._direct_mode:
            if self._proc_handle is not None:
                try:
                    terminate_process(self._proc_handle)
                except OSError:
                    pass
        else:
            self._popen.terminate()


def _normalise_argv(argv):
    if isinstance(argv, (str, bytes)):
        raise WSpawnError("argv must be a sequence of arguments, not a single string", kind="badarg")
    try:
        items = [os.fspath(item) for item in argv]
    except TypeError as exc:
        raise WSpawnError("argv must be an iterable of paths: %s" % exc, kind="badarg") from exc
    if not items:
        raise WSpawnError("argv must not be empty", kind="badarg")
    return items


def _normalise_handles(inherit):
    if inherit is None:
        return ()
    if isinstance(inherit, int):
        raise WSpawnError("inherit must be a sequence of handles, not a single handle", kind="badarg")
    try:
        return tuple(int(item) for item in inherit)
    except (TypeError, ValueError) as exc:
        raise WSpawnError("inherit must contain integer handles: %s" % exc, kind="badarg") from exc


def _quote_arg(arg):
    """Quote a command line argument for Windows CreateProcess."""
    # Simple quoting: if it contains spaces or special chars, wrap in quotes
    if not arg:
        return '""'

    # Check if quoting is needed
    needs_quote = False
    for c in arg:
        if c in ' \t\n\v"':
            needs_quote = True
            break

    if not needs_quote:
        return arg

    # Escape backslashes before quotes and wrap in quotes
    result = ['"']
    num_backslashes = 0
    for c in arg:
        if c == '\\':
            num_backslashes += 1
        elif c == '"':
            # Double the backslashes before the quote, then add escaped quote
            result.append('\\' * (num_backslashes * 2 + 1))
            result.append('"')
            num_backslashes = 0
        else:
            # Flush any pending backslashes
            result.append('\\' * num_backslashes)
            result.append(c)
            num_backslashes = 0

    # Flush remaining backslashes (before closing quote, they need to be doubled)
    result.append('\\' * (num_backslashes * 2))
    result.append('"')
    return ''.join(result)


def _build_command_line(argv):
    """Build a Windows command line string from argv list."""
    return ' '.join(_quote_arg(arg) for arg in argv)


def _to_windows_handle(obj):
    """Convert a file-like object or integer to a Windows handle.

    On Windows, Python file objects use C runtime file descriptors (fds),
    which need to be converted to Windows handles using _get_osfhandle().
    Integer values are assumed to already be Windows handles.
    """
    if obj is None:
        return None

    if obj is subprocess.DEVNULL:
        return 'DEVNULL'

    if isinstance(obj, int):
        # Assume it's already a Windows handle
        return obj

    if hasattr(obj, 'fileno'):
        fd = obj.fileno()
        # Convert fd to Windows handle
        import msvcrt
        return msvcrt.get_osfhandle(fd)

    raise WSpawnError("cannot convert %r to a handle" % (obj,), kind="badarg")


def spawn(argv, inherit=(), stdin=None, stdout=None, stderr=None):
    """Start a helper process, handing it the objects named in ``inherit``.

    Returns a :class:`SpawnedProcess`.

    On Windows, uses CreateProcess with PROC_THREAD_ATTRIBUTE_HANDLE_LIST
    to ensure only the specified handles are inherited, and they keep
    the same numeric values in the child process.
    """
    command = _normalise_argv(argv)
    handles = _normalise_handles(inherit)

    # Normalize std handles to Windows handles
    stdin_handle = _to_windows_handle(stdin)
    stdout_handle = _to_windows_handle(stdout)
    stderr_handle = _to_windows_handle(stderr)

    if is_windows():
        # Use direct Windows API for precise handle control
        try:
            # Handle DEVNULL case - open NUL device
            devnull_handle = None
            devnull_fd = None

            if stdout_handle == 'DEVNULL' or stderr_handle == 'DEVNULL' or stdin_handle == 'DEVNULL':
                # Open NUL device for writing
                devnull_fd = os.open('NUL', os.O_WRONLY)
                import msvcrt
                devnull_handle = msvcrt.get_osfhandle(devnull_fd)

                if stdout_handle == 'DEVNULL':
                    stdout_handle = devnull_handle
                if stderr_handle == 'DEVNULL':
                    stderr_handle = devnull_handle
                if stdin_handle == 'DEVNULL':
                    stdin_handle = devnull_handle

            cmd_line = _build_command_line(command)

            proc_handle, thread_handle, pid = create_process_with_handle_list(
                cmd_line,
                list(handles),
                stdin=stdin_handle,
                stdout=stdout_handle,
                stderr=stderr_handle,
            )

            # Close the thread handle (we don't need it)
            try:
                close_handle(thread_handle)
            except OSError:
                pass

            return SpawnedProcess(pid, handles, proc_handle=proc_handle, thread_handle=None)

        except OSError as exc:
            raise WSpawnError(str(exc), kind="os") from exc
    else:
        # Non-Windows fallback using subprocess
        kwargs = {
            "close_fds": True,
            "stdin": stdin,
            "stdout": stdout,
            "stderr": stderr,
        }

        try:
            popen = subprocess.Popen(command, **kwargs)
        except OSError as exc:
            raise WSpawnError(str(exc), kind="os") from exc
        return SpawnedProcess(popen, handles)

